import{_ as t,o as a,c as s,a0 as n}from"./chunks/framework.BE1i3JtZ.js";const h=JSON.parse('{"title":"unix-router-guard 导航拦截插件设计规格 (2026-09-15)","description":"","frontmatter":{},"headers":[],"relativePath":"superpowers/specs/2026-09-15-unix-router-guard-plugin-design.md","filePath":"superpowers/specs/2026-09-15-unix-router-guard-plugin-design.md"}'),o={name:"superpowers/specs/2026-09-15-unix-router-guard-plugin-design.md"};function d(r,e,c,i,p,l){return a(),s("div",null,[...e[0]||(e[0]=[n(`<h1 id="unix-router-guard-导航拦截插件设计规格-2026-09-15" tabindex="-1">unix-router-guard 导航拦截插件设计规格 (2026-09-15) <a class="header-anchor" href="#unix-router-guard-导航拦截插件设计规格-2026-09-15" aria-label="Permalink to &quot;unix-router-guard 导航拦截插件设计规格 (2026-09-15)&quot;">​</a></h1><h2 id="_1-概述" tabindex="-1">1. 概述 <a class="header-anchor" href="#_1-概述" aria-label="Permalink to &quot;1. 概述&quot;">​</a></h2><h3 id="_1-1-背景" tabindex="-1">1.1 背景 <a class="header-anchor" href="#_1-1-背景" aria-label="Permalink to &quot;1.1 背景&quot;">​</a></h3><p>项目现有 <a href="https://github.com/cq112233/unibestX/blob/main/src/router/interceptor.uts" target="_blank" rel="noreferrer">src/router/interceptor.uts</a> 已经实现了导航拦截，但它<strong>与业务强绑定</strong>：登录策略常量（<code>LOGIN_PAGE</code>、<code>EXCLUDE_LOGIN_PATH_LIST</code>）、token 校验（<code>useTokenStore</code>）、TabBar 选中态（<code>src/tabbar/helper</code>）全部内联在 <code>doIntercept()</code> 里，无法作为通用能力复用，也无法独立分发。</p><p>另有一份 <a href="./2026-09-14-router-guard-design.html">2026-09-14-router-guard-design.md</a> 规划了 <code>src/router</code> 内部的<strong>工厂式守卫重构</strong>，那仍然是在业务工程内的改造，不属于本规格范围。</p><p><code>feat/router-guard</code> 分支（2026-09-15 上午）曾实现过一版同类插件，但它的公开形态是 <code>installRouterGuard({ guards, dispatch })</code> + 守卫对象数组、且要求宿主注入 <code>RouterDispatch</code> 才能跳 TabBar 页。本规格<strong>不沿用</strong>那一版，改为 <code>createRouter()</code> + <code>beforeEach(fn)</code> 的注册式形态（更贴 vue-router），并把 TabBar 的差异收敛为<strong>可选</strong>的 <code>resolveRedirectApi</code> 回调。该分支的 <code>uni_modules/unix-router-guard/</code> 与本规格产出的同名目录<strong>不共存</strong>：当前分支 <code>refactor/tabbar-helper-split</code> 上没有该目录，本规格从零创建。</p><p>本规格新增一个 <strong>与业务零耦合</strong> 的 uni_modules 插件 <code>unix-router-guard</code>：只提供「导航拦截 + 守卫链 + 跳转门面」，<strong>不含任何业务规则</strong>（不做登录判断、不依赖 Pinia / store / 项目 utils）。</p><h3 id="_1-2-目标" tabindex="-1">1.2 目标 <a class="header-anchor" href="#_1-2-目标" aria-label="Permalink to &quot;1.2 目标&quot;">​</a></h3><ol><li>把 vue-router 的<strong>导航控制</strong>部分（<code>beforeEach</code> / <code>afterEach</code> / <code>next</code> 三种裁决 / 重定向 / 中止）搬到 uni-app X，API 形状与 vue-router 3 一致，降低使用者的心智负担；</li><li>一个 <code>createRouter()</code> 完成拦截器安装，业务只需在一个守卫里写自己的规则；</li><li>纯函数层（URL 解析/规范化/序列化、守卫链执行器）可脱离 uni 运行时在 node 里跑决策矩阵测试；</li><li>只依赖 <code>vue</code>（实际上只依赖 <code>uni</code> 全局，<code>vue</code> 都不需要），可直接发布插件市场。</li></ol><h3 id="_1-3-非目标-明确不做" tabindex="-1">1.3 非目标（明确不做） <a class="header-anchor" href="#_1-3-非目标-明确不做" aria-label="Permalink to &quot;1.3 非目标（明确不做）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>不做的能力</th><th>原因</th></tr></thead><tbody><tr><td><code>routes</code> 路由表 / 命名路由 / 动态段 <code>:id</code></td><td>本插件只做拦截；uni-app X 页面路径由 <code>pages.json</code> 静态声明</td></tr><tr><td><code>&lt;router-view&gt;</code></td><td>uni-app X 页面是原生页面栈，没有视图出口可渲染</td></tr><tr><td><code>useRoute()</code> / <code>router.currentRoute</code></td><td>页面取参继续用 uni 原生的 <code>onLoad(options)</code>；插件无法可靠覆盖所有进入路径（直链、返回、原生返回键）</td></tr><tr><td>异步守卫（<code>await</code> 后再裁决）</td><td><code>uni.addInterceptor</code> 的 <code>invoke</code> 必须<strong>同步</strong>返回 boolean，形态上写不出来</td></tr><tr><td><code>router.beforeResolve()</code></td><td>没有组件内守卫，没有与之对应的时序</td></tr><tr><td><code>next(error)</code> / <code>router.onError()</code></td><td>同步拦截形态下没有失败通道</td></tr><tr><td><code>NavigationDuplicated</code> 重复导航报错</td><td>uni 页面栈允许同一页面重复入栈，模拟它会破坏正常用法</td></tr><tr><td><code>to.name</code> / <code>to.meta</code> / <code>to.matched</code> / <code>to.hash</code></td><td>无路由表则无来源</td></tr></tbody></table><h2 id="_2-与-vue-router-的-api-对齐" tabindex="-1">2. 与 vue-router 的 API 对齐 <a class="header-anchor" href="#_2-与-vue-router-的-api-对齐" aria-label="Permalink to &quot;2. 与 vue-router 的 API 对齐&quot;">​</a></h2><table tabindex="0"><thead><tr><th>vue-router 3</th><th>本插件</th><th>说明</th></tr></thead><tbody><tr><td><code>new VueRouter({ routes })</code></td><td><code>createRouter({ apis, redirectApi })</code></td><td>无 <code>routes</code></td></tr><tr><td><code>router.beforeEach((to, from, next) =&gt; {})</code></td><td><strong>签名完全一致</strong></td><td>触发本次导航的 API 名放在 <code>to.api</code>，见 3.2</td></tr><tr><td><code>router.afterEach((to, from) =&gt; {})</code></td><td><strong>签名完全一致</strong></td><td>afterEach 无 <code>next</code></td></tr><tr><td><code>next()</code> / <code>next(&#39;/x&#39;)</code> / <code>next(false)</code></td><td><strong>完全一致</strong></td><td>见 3.3</td></tr><tr><td><code>router.push(location)</code></td><td>一致（<code>string</code> 或 <code>{ path, query }</code>）</td><td>见 3.4</td></tr><tr><td><code>router.replace(location)</code></td><td>一致</td><td></td></tr><tr><td><code>router.go(n)</code> / <code>router.back()</code></td><td><code>router.back()</code> / <code>router.back(2)</code></td><td>同 <code>next</code>，用剩余参数容纳两种调用形态</td></tr><tr><td>—</td><td><code>router.relaunch(location)</code></td><td>uni 特有：关闭所有页面打开</td></tr><tr><td>—</td><td><code>router.switchTab(location)</code></td><td>uni 特有：只跳 tabBar 页面</td></tr><tr><td><code>to.path</code> / <code>to.fullPath</code> / <code>to.query</code> / <code>to.params</code></td><td>一致</td><td><code>params</code> 恒为空对象，仅为形态一致</td></tr><tr><td><code>router.beforeEach</code> 返回注销函数</td><td>一致</td><td></td></tr></tbody></table><p><strong>两个刻意保留的差异</strong>（都会写进 readme）：</p><ol><li><code>to.params</code> 恒为 <code>{}</code>（无路由表 ⇒ 无动态段）。保留该字段只为让 vue-router 使用者的读取代码不用改。</li><li><code>afterEach</code> 在<strong>放行时同步触发</strong>，不是在「导航确认成功后」。理由见 5.4。</li><li><code>to.query</code> / <code>to.params</code> 是 <code>Map&lt;string, string&gt;</code> 而非对象，读法为 <code>to.query.get(&#39;id&#39;)</code> 而非 <code>to.query.id</code>。理由见 3.2（UTS 无法动态构造 <code>UTSJSONObject</code>）。</li></ol><p><strong>一个刻意的补充</strong>：<code>to.api</code> / <code>from.api</code> 是本插件新增字段，值为触发本次导航的 uni API 名（<code>navigateTo</code> / <code>switchTab</code> …）。vue-router 没有这个概念，但排查「谁触发了这次跳转」时是刚需；放在 <code>to</code> 上而不是加第 4 个守卫参数，是为了让守卫签名与 vue-router <strong>逐字相同</strong>，使用者可以直接照搬 vue-router 的守卫写法。</p><h2 id="_3-公开-api" tabindex="-1">3. 公开 API <a class="header-anchor" href="#_3-公开-api" aria-label="Permalink to &quot;3. 公开 API&quot;">​</a></h2><h3 id="_3-1-创建与选项" tabindex="-1">3.1 创建与选项 <a class="header-anchor" href="#_3-1-创建与选项" aria-label="Permalink to &quot;3.1 创建与选项&quot;">​</a></h3><div class="language-uts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">uts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>import { createRouter } from &#39;@/uni_modules/unix-router-guard&#39;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>const router = createRouter({</span></span>
<span class="line"><span>  apis: [&#39;navigateTo&#39;, &#39;redirectTo&#39;, &#39;reLaunch&#39;, &#39;switchTab&#39;, &#39;navigateBack&#39;],</span></span>
<span class="line"><span>  redirectApi: &#39;navigateTo&#39;,</span></span>
<span class="line"><span>  maxRedirectDepth: 5,</span></span>
<span class="line"><span>  debug: false</span></span>
<span class="line"><span>})</span></span></code></pre></div><div class="language-uts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">uts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>export type RouterOptions = {</span></span>
<span class="line"><span>  /** 需要拦截的 API 名；不传用默认 5 个 */</span></span>
<span class="line"><span>  apis ?: Array&lt;string&gt;</span></span>
<span class="line"><span>  /** 守卫裁决重定向时统一使用的 API；不传用 &#39;navigateTo&#39; */</span></span>
<span class="line"><span>  redirectApi ?: string</span></span>
<span class="line"><span>  /** 同一次导航的重定向链深度上限，超过则拒绝重定向；不传用 5 */</span></span>
<span class="line"><span>  maxRedirectDepth ?: number</span></span>
<span class="line"><span>  /** 打印拦截链路日志；不传用 false */</span></span>
<span class="line"><span>  debug ?: boolean</span></span>
<span class="line"><span>  /** 裁决重定向时按 url 决定用哪个跳转 API（如「是 TabBar 页就 switchTab」）；不传则恒用 redirectApi */</span></span>
<span class="line"><span>  resolveRedirectApi ?: (url: string) =&gt; string</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>（<code>?:</code> 是本项目已在用的可选字段写法，见 <a href="https://github.com/cq112233/unibestX/blob/main/src/utils/upload/index.uts" target="_blank" rel="noreferrer">src/utils/upload/index.uts</a> 的 <code>onProgress?: (progress: number) =&gt; void</code>；因此 <code>createRouter()</code> 与 <code>createRouter({ debug: true })</code> 都合法。）</p><p><code>createRouter()</code> 内部完成 <code>uni.addInterceptor</code> 安装（幂等：重复调用先卸载上一次）。</p><h3 id="_3-2-守卫" tabindex="-1">3.2 守卫 <a class="header-anchor" href="#_3-2-守卫" aria-label="Permalink to &quot;3.2 守卫&quot;">​</a></h3><div class="language-uts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">uts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// 前置守卫：to / from / next（与 vue-router 逐字相同）</span></span>
<span class="line"><span>const unregister = router.beforeEach((to, from, next) =&gt; {</span></span>
<span class="line"><span>  if (needLogin(to.path) &amp;&amp; !hasToken()) {</span></span>
<span class="line"><span>    next(\`/src/sub/auth/login?redirect=\${to.fullPath}\`)</span></span>
<span class="line"><span>    return</span></span>
<span class="line"><span>  }</span></span>
<span class="line"><span>  if (needLogin(to.path) &amp;&amp; to.api == &#39;switchTab&#39;) {</span></span>
<span class="line"><span>    // to.api 告诉你是哪个 uni API 触发的这次跳转</span></span>
<span class="line"><span>  }</span></span>
<span class="line"><span>  next()</span></span>
<span class="line"><span>})</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// 后置守卫：to / from</span></span>
<span class="line"><span>router.afterEach((to, from) =&gt; {</span></span>
<span class="line"><span>  console.log(&#39;navigation done&#39;, to.api, to.fullPath)</span></span>
<span class="line"><span>})</span></span>
<span class="line"><span></span></span>
<span class="line"><span>unregister() // 注销该守卫</span></span></code></pre></div><div class="language-uts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">uts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/** 路由目标：一次导航的目标或来源 */</span></span>
<span class="line"><span>export type RouteTarget = {</span></span>
<span class="line"><span>  /** 原始 url 字符串（保留 query） */</span></span>
<span class="line"><span>  url: string</span></span>
<span class="line"><span>  /** 规范化路径（带前导 /，不含 query） */</span></span>
<span class="line"><span>  path: string</span></span>
<span class="line"><span>  /** path + query 的完整形式 */</span></span>
<span class="line"><span>  fullPath: string</span></span>
<span class="line"><span>  /** 查询参数键值对，值恒为 string（URL 是唯一跨页面传参通道） */</span></span>
<span class="line"><span>  query: Map&lt;string, string&gt;</span></span>
<span class="line"><span>  /** 与 vue-router 形态对齐：本插件无路由表，恒为空 Map */</span></span>
<span class="line"><span>  params: Map&lt;string, string&gt;</span></span>
<span class="line"><span>  /** 本插件扩展字段：触发本次导航的 uni API 名（navigateTo / redirectTo / reLaunch / switchTab / navigateBack） */</span></span>
<span class="line"><span>  api: string</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>/** next 回调：放行 / 改跳 / 中止 */</span></span>
<span class="line"><span>export type Next = (...args: Array&lt;any&gt;) =&gt; void</span></span>
<span class="line"><span></span></span>
<span class="line"><span>export type NavigationGuard = (to: RouteTarget, from: RouteTarget, next: Next) =&gt; void</span></span>
<span class="line"><span>export type AfterNavigationHook = (to: RouteTarget, from: RouteTarget) =&gt; void</span></span></code></pre></div><p><strong><code>query</code> 为什么是 <code>Map&lt;string, string&gt;</code> 而不是对象</strong>：<code>to.query</code> 必须由 url 字符串<strong>动态构造</strong>，而 UTS 的 <code>UTSJSONObject</code> 只提供静态的 <code>assign</code> / <code>keys</code>，没有可用的动态写入接口（本项目对它的用法全是「读」，见 <code>uni_modules/lime-i18n/common/composer.uts</code>）。<code>Map</code> 则是本项目既有形态 —— <code>src/router/interceptor.uts:141</code> 的 <code>UrlObj.query</code> 就是 <code>Map&lt;string, string&gt;</code>。</p><p>代价是读法从 vue-router 的 <code>to.query.id</code> 变成 <code>to.query.get(&#39;id&#39;)</code>，这条差异写进 readme。</p><p><strong><code>Next</code> 为什么用 <code>...args: Array&lt;any&gt;</code></strong>：<a href="https://github.com/cq112233/unibestX/blob/main/.agents/rules/uniappx.md#L215" target="_blank" rel="noreferrer">.agents/rules/uniappx.md:215</a> 规定「UTS 的联合类型目前仅支持与 <code>null</code> 的联合，<code>string | number</code> 这类需声明为 <code>any</code>」。而 vue-router 的 <code>next()</code> / <code>next(&#39;/x&#39;)</code> / <code>next(false)</code> 三种形态的<strong>参数个数与类型都不同</strong>，只有剩余参数能同时容纳它们并保持零参数调用合法。剩余参数在本项目已有实证（<code>uni_modules/lime-i18n/common/util.uts:139</code> 的 <code>parseArgs(...args: Array&lt;any&gt;)</code>）。</p><p>守卫链<strong>同步</strong>执行：<code>router.beforeEach</code> 注册顺序即执行顺序。</p><h3 id="_3-3-next-裁决表" tabindex="-1">3.3 next 裁决表 <a class="header-anchor" href="#_3-3-next-裁决表" aria-label="Permalink to &quot;3.3 next 裁决表&quot;">​</a></h3><table tabindex="0"><thead><tr><th>调用形态</th><th>裁决</th><th>说明</th></tr></thead><tbody><tr><td><code>next()</code></td><td>放行</td><td>链条继续，交给下一个守卫</td></tr><tr><td><code>next(null)</code></td><td>放行</td><td>与 vue-router 3 一致（<code>null</code>/<code>undefined</code> 均视为放行）</td></tr><tr><td><code>next(&#39;/x&#39;)</code> 或 <code>next(&#39;x?a=1&#39;)</code></td><td>短路</td><td>中止本次导航并改跳该地址</td></tr><tr><td><code>next(false)</code></td><td>短路</td><td>中止本次导航，且不做任何跳转</td></tr><tr><td>其他值（如 <code>next(123)</code>）</td><td>短路 + 警告</td><td><strong>fail-safe</strong>：取值非法时按中止处理，不静默放行</td></tr><tr><td>守卫执行完仍未调用 <code>next</code></td><td>短路 + 警告</td><td>vue-router 会挂起导航，同步形态不能挂，必须给确定结果</td></tr></tbody></table><p>「短路」= 不再执行后续守卫，也不触发本次导航的 <code>afterEach</code>。</p><h3 id="_3-4-跳转门面" tabindex="-1">3.4 跳转门面 <a class="header-anchor" href="#_3-4-跳转门面" aria-label="Permalink to &quot;3.4 跳转门面&quot;">​</a></h3><div class="language-uts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">uts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>router.push(&#39;/src/sub/user/detail?id=1&#39;)                         // 字符串形态</span></span>
<span class="line"><span>router.push({ path: &#39;/src/sub/user/detail&#39;, query: { id: 1 } })  // 对象形态</span></span>
<span class="line"><span>router.replace({ path: &#39;/src/sub/auth/login&#39; })</span></span>
<span class="line"><span>router.relaunch(&#39;/src/pages/index/index&#39;)</span></span>
<span class="line"><span>router.switchTab(&#39;/src/pages/me/me&#39;)</span></span>
<span class="line"><span>router.back()      // 等价 back(1)</span></span>
<span class="line"><span>router.back(2)</span></span></code></pre></div><div class="language-uts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">uts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>export type Router = {</span></span>
<span class="line"><span>  beforeEach: (guard: NavigationGuard) =&gt; () =&gt; void</span></span>
<span class="line"><span>  afterEach: (hook: AfterNavigationHook) =&gt; () =&gt; void</span></span>
<span class="line"><span>  push: (to: any) =&gt; Promise&lt;any&gt; | null</span></span>
<span class="line"><span>  replace: (to: any) =&gt; Promise&lt;any&gt; | null</span></span>
<span class="line"><span>  relaunch: (to: any) =&gt; Promise&lt;any&gt; | null</span></span>
<span class="line"><span>  switchTab: (to: any) =&gt; Promise&lt;any&gt; | null</span></span>
<span class="line"><span>  back: (...args: Array&lt;number&gt;) =&gt; void</span></span>
<span class="line"><span>  uninstall: () =&gt; void</span></span>
<span class="line"><span>}</span></span></code></pre></div><ul><li><code>to</code> 声明为 <code>any</code> 而非 <code>string | UTSJSONObject</code>：<strong>UTS 不支持任意类型联合</strong>（同上规则），要同时接受字符串与对象字面量只能声明为 <code>any</code>，这也是 vue-router 使用者最熟悉的两种写法。</li><li><code>back</code> 同样用剩余参数，<code>router.back()</code> 与 <code>router.back(2)</code> 都合法（默认退 1 层）。</li><li>返回值与底层 uni API 一致（<code>Promise&lt;...&gt; | null</code>）；导航被守卫拦截时返回 <code>null</code>。</li><li>跳转门面是<strong>薄封装</strong>：守卫挂在 <code>uni.addInterceptor</code> 上，因此业务代码直接调 <code>uni.navigateTo</code> 同样会被拦截，门面只为写法一致与便于测试。</li></ul><h4 id="_3-4-1-对象形态的内部读取方式" tabindex="-1">3.4.1 对象形态的内部读取方式 <a class="header-anchor" href="#_3-4-1-对象形态的内部读取方式" aria-label="Permalink to &quot;3.4.1 对象形态的内部读取方式&quot;">​</a></h4><p><code>any</code> 位置的对象字面量在 UTS 里编译为 <strong><code>UTSJSONObject</code></strong>（<code>_uO(...)</code>，见红线 1.1.10 的编译产物说明），因此内部用 <code>getString(&#39;path&#39;)</code> / <code>getJSON(&#39;query&#39;)</code> 读取，<strong>绝不对它做 <code>as SomeType</code> 强转</strong> —— <code>as</code> 是 Kotlin 非空转换，<code>UTSJSONObject</code> → data class 会直接抛 <code>ClassCastException</code>（红线 1.3.1 / 1.3.17）。</p><p>嵌套对象字面量 + <code>getJSON</code> 在本项目已有实证：<code>uni_modules/lime-i18n/common/composer.uts:60</code> 读的正是字面量里的嵌套对象。</p><p><strong>由此产生一条必须写进 readme 的使用约束</strong>：对象形态<strong>只能直接传字面量</strong>，不能先声明成变量再传。</p><div class="language-uts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">uts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// ✅ 正确：直接传字面量 → 编译为 UTSJSONObject，内部按 Json 读取</span></span>
<span class="line"><span>router.push({ path: &#39;/src/sub/user/detail&#39;, query: { id: 1 } })</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// ❌ 错误：变量带显式 type 标注 → 编译为 Kotlin data class，内部按 UTSJSONObject 读取时抛异常</span></span>
<span class="line"><span>type MyLoc = { path: string }</span></span>
<span class="line"><span>const loc: MyLoc = { path: &#39;/src/sub/user/detail&#39; }</span></span>
<span class="line"><span>router.push(loc)</span></span></code></pre></div><p>因此插件<strong>不导出</strong> <code>RouteLocation</code> 之类的对象类型 —— 导出它反而会诱导使用者写出上面那条错误写法。</p><h4 id="_3-4-2-query-值的序列化规则" tabindex="-1">3.4.2 query 值的序列化规则 <a class="header-anchor" href="#_3-4-2-query-值的序列化规则" aria-label="Permalink to &quot;3.4.2 query 值的序列化规则&quot;">​</a></h4><p>URL 是唯一跨页面通道，值最终只能是字符串：</p><table tabindex="0"><thead><tr><th>值类型</th><th>序列化结果</th></tr></thead><tbody><tr><td><code>string</code> / <code>number</code> / <code>boolean</code></td><td>转字符串后 <code>encodeURIComponent</code></td></tr><tr><td>数组</td><td>元素转字符串后用 <code>,</code> 连接（<code>{ ids: [1, 2] }</code> → <code>?ids=1,2</code>）</td></tr><tr><td>对象</td><td><code>JSON.stringify</code> 后再编码</td></tr><tr><td><code>null</code></td><td>忽略该键</td></tr></tbody></table><p>类型判定用 <code>typeof</code> 与 <code>isArray()</code>，键遍历用 <code>UTSJSONObject.toMap()</code>（两者在本项目均有实证：<code>uni_modules/lime-i18n/common/util.uts:141</code>、<code>uni_modules/lime-i18n/common/composer.uts:99</code>）。</p><h3 id="_3-5-卸载" tabindex="-1">3.5 卸载 <a class="header-anchor" href="#_3-5-卸载" aria-label="Permalink to &quot;3.5 卸载&quot;">​</a></h3><div class="language-uts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">uts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>router.uninstall()   // 移除全部已安装拦截器</span></span></code></pre></div><h2 id="_4-架构与文件结构" tabindex="-1">4. 架构与文件结构 <a class="header-anchor" href="#_4-架构与文件结构" aria-label="Permalink to &quot;4. 架构与文件结构&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>uni_modules/unix-router-guard/</span></span>
<span class="line"><span>├── package.json          # main: &quot;index.uts&quot;，dcloudext.type: &quot;uts&quot;</span></span>
<span class="line"><span>├── readme.md</span></span>
<span class="line"><span>├── changelog.md</span></span>
<span class="line"><span>├── index.uts             # 唯一门面：单层 export，禁止多层转发</span></span>
<span class="line"><span>└── lib/</span></span>
<span class="line"><span>    ├── types.uts         # 零点依赖叶子：全部 type + createRouteTarget 之外的纯类型</span></span>
<span class="line"><span>    ├── url.uts           # 纯函数：解析 query / 规范化路径 / 相对路径解析 / 序列化</span></span>
<span class="line"><span>    ├── guard.uts         # 守卫注册表 + 同步执行器（runBeforeGuards / runAfterGuards）</span></span>
<span class="line"><span>    ├── interceptor.uts   # addInterceptor 安装/卸载 + 裁决派发 + 重定向深度保护</span></span>
<span class="line"><span>    └── router.uts        # createRouter 工厂（对象字面量 + 箭头函数，不用 class）</span></span></code></pre></div><p>依赖方向（严格单向，无环）：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>types.uts ──&gt; url.uts ──&gt; guard.uts ──&gt; router.uts ──&gt; index.uts</span></span>
<span class="line"><span>                    └──&gt; interceptor.uts ──┘</span></span></code></pre></div><ul><li><code>types.uts</code> 零依赖，是打破环的关键：<code>guard.uts</code> 与 <code>interceptor.uts</code> 都要用类型，若类型放在 <code>router.uts</code> 就会成环。</li><li><code>index.uts</code> <strong>只做单层 <code>export *</code></strong>，<code>lib/*</code> 之间用 <code>import</code> 而非 <code>export *</code>（红线 1.1.12）。</li><li><code>createRouter()</code> 返回 <code>Router</code> 对象字面量（字段为箭头函数）：UTS <strong>禁止传递 Class 实例</strong>（<code>UTS110111151</code>），因此不能用 <code>class</code>。</li></ul><h2 id="_5-关键实现细节" tabindex="-1">5. 关键实现细节 <a class="header-anchor" href="#_5-关键实现细节" aria-label="Permalink to &quot;5. 关键实现细节&quot;">​</a></h2><h3 id="_5-1-routetarget-构建-url-uts" tabindex="-1">5.1 RouteTarget 构建（<code>url.uts</code>） <a class="header-anchor" href="#_5-1-routetarget-构建-url-uts" aria-label="Permalink to &quot;5.1 RouteTarget 构建（\`url.uts\`）&quot;">​</a></h3><p>沿用 <a href="https://github.com/cq112233/unibestX/blob/main/src/router/interceptor.uts" target="_blank" rel="noreferrer">src/router/interceptor.uts</a> 已验证的规则，一条都不能少：</p><ol><li>按 <code>?</code> 切分 url，前段为 path，后段按 <code>&amp;</code> / <code>=</code> 解析为 query（值做 <code>decodeURIComponent</code>）；</li><li>补前导 <code>/</code>（<code>src/pages/x</code> → <code>/src/pages/x</code>）；</li><li><strong>相对路径解析</strong>：不以 <code>/</code> 开头、且不是 <code>plugin://</code> / <code>http://</code> / <code>https://</code> 的路径，按<strong>当前页目录</strong>拼成绝对路径（当前页取 <code>getCurrentPages()</code> 末页的 <code>route</code>）；</li><li><code>fullPath</code> = 规范化 path + 原始 query 串。</li></ol><p>对应的纯函数签名（可在 node 里单测）：</p><div class="language-uts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">uts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>export function parseUrl(url: string): RouteTarget</span></span>
<span class="line"><span>export function normalizePath(path: string): string</span></span>
<span class="line"><span>export function resolveRelativePath(path: string, currentPagePath: string): string</span></span>
<span class="line"><span>export function buildFullPath(path: string, queryStr: string): string</span></span></code></pre></div><p>相对路径解析依赖「当前页路径」，把它作为<strong>参数</strong>传入而不是在函数里调 <code>getCurrentPages()</code>，才能脱离运行时测试。</p><h3 id="_5-2-拦截器安装与-options-强转-interceptor-uts" tabindex="-1">5.2 拦截器安装与 options 强转（<code>interceptor.uts</code>） <a class="header-anchor" href="#_5-2-拦截器安装与-options-强转-interceptor-uts" aria-label="Permalink to &quot;5.2 拦截器安装与 options 强转（\`interceptor.uts\`）&quot;">​</a></h3><div class="language-uts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">uts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>export function installInterceptor(api: string): void {</span></span>
<span class="line"><span>  uni.addInterceptor(api, createInterceptor(api))</span></span>
<span class="line"><span>}</span></span></code></pre></div><p><code>invoke(options: any)</code> 取 url 时<strong>必须按 API 分别强转</strong>（App 原生端各 API 的 options 是不同 Kotlin 类，混用会 ClassCastException）：</p><div class="language-uts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">uts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>function extractUrl(api: string, options: any): string {</span></span>
<span class="line"><span>  if (options == null) { return &#39;&#39; }</span></span>
<span class="line"><span>  // #ifdef APP</span></span>
<span class="line"><span>  if (api == &#39;navigateTo&#39;) { return (options as NavigateToOptions).url }</span></span>
<span class="line"><span>  if (api == &#39;redirectTo&#39;) { return (options as RedirectToOptions).url }</span></span>
<span class="line"><span>  if (api == &#39;reLaunch&#39;) { return (options as ReLaunchOptions).url }</span></span>
<span class="line"><span>  if (api == &#39;switchTab&#39;) { return (options as SwitchTabOptions).url }</span></span>
<span class="line"><span>  // #endif</span></span>
<span class="line"><span>  // #ifndef APP</span></span>
<span class="line"><span>  const obj = options as UTSJSONObject</span></span>
<span class="line"><span>  return (obj.url != null) ? (obj.url as string) : &#39;&#39;</span></span>
<span class="line"><span>  // #endif</span></span>
<span class="line"><span>  return &#39;&#39;</span></span>
<span class="line"><span>}</span></span></code></pre></div><ul><li><strong>只对 5 个内置 API 做 App 端强转</strong>；<code>apis</code> 里由使用者追加的自定义 API 一律走 <code>UTSJSONObject</code> 分支，避免 <code>as</code> 抛异常（<code>as</code> 是非空转换，类型不匹配会 NPE —— 红线 1.3.17）。</li><li><code>navigateBack</code> 没有 url，同样走 <code>UTSJSONObject</code> 分支，其 <code>to</code> 用一个「回退目标占位」：<code>url</code> 为 <code>&#39;&#39;</code>，<code>path</code> 取当前页路径，<code>api</code> 为 <code>&#39;navigateBack&#39;</code>。</li><li>与现有实现等价：<code>invoke</code> 同步返回 <code>false</code> 即取消本次导航。</li></ul><h3 id="_5-3-裁决派发与重定向深度保护" tabindex="-1">5.3 裁决派发与重定向深度保护 <a class="header-anchor" href="#_5-3-裁决派发与重定向深度保护" aria-label="Permalink to &quot;5.3 裁决派发与重定向深度保护&quot;">​</a></h3><p>守卫返回「改跳」时由插件统一派发：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>pass  → 返回 true，放行</span></span>
<span class="line"><span>改跳  → 短路并按下方规则选 API 调用；返回 false（取消原导航）</span></span>
<span class="line"><span>中止  → 返回 false，不做任何跳转</span></span></code></pre></div><p><strong>改跳用哪个 uni API</strong>，按两步决定：</p><ol><li>传了 <code>resolveRedirectApi</code> → 用它按 url 逐个决定（如「是 TabBar 页就返回 <code>switchTab</code>」）；</li><li>没传 → 恒用 <code>redirectApi</code>（默认 <code>navigateTo</code>）。</li></ol><p>第 1 步存在的必要性：改跳目标若是 TabBar 页面，<code>uni.navigateTo</code> 会<strong>直接失败</strong>（uni 规定 TabBar 页只能用 <code>switchTab</code>）。插件对宿主的 TabBar 清单零知识，所以这里只留一个<strong>可选</strong>的纯函数钩子 —— 不传也能用，传了就能处理 TabBar 改跳，且不引入任何项目内依赖。</p><p>重定向派发会<strong>再次触发拦截器</strong>（这是预期行为，也是「登录页放行」这类写法能终止链条的原因）。防死循环用<strong>递增 + 放行归零</strong>策略：</p><ul><li>每次重定向 <code>redirectDepth += 1</code>；</li><li>任一环节<strong>放行</strong>（含 <code>navigateBack</code>）时 <code>redirectDepth = 0</code>；</li><li><code>redirectDepth &gt; maxRedirectDepth</code> 时<strong>拒绝重定向</strong>（按静默中止处理）并打警告。</li></ul><p>该策略不需要依赖「interceptor 的 invoke 是否同步执行」这一未证实前提。</p><h3 id="_5-4-aftereach-的触发时机" tabindex="-1">5.4 afterEach 的触发时机 <a class="header-anchor" href="#_5-4-aftereach-的触发时机" aria-label="Permalink to &quot;5.4 afterEach 的触发时机&quot;">​</a></h3><p><code>afterEach</code> 在<strong>守卫链放行之后、调用 uni API 之前同步触发</strong>。</p><p>理由：<code>afterEach</code> 在 vue-router 里依赖「导航确认」这一时机，而 uni 侧只能靠 interceptor 的 <code>success</code> 回调，该回调的跨平台行为<strong>没有官方逐平台说明</strong>（<a href="./2026-09-14-router-guard-design.html">2026-09-14 规格 §6.2</a> 已把这条列为待真机验证项）。<code>afterEach</code> 的典型用途是埋点与 TabBar 选中态同步，对「导航随后可能失败」不敏感，因此优先选<strong>确定会触发</strong>的时机。</p><p>真机验证后若确认 <code>success</code> 回调可靠，可切换为 success 触发 —— 改动只在 <code>interceptor.uts</code> 一处。</p><h2 id="_6-红线遵守" tabindex="-1">6. 红线遵守 <a class="header-anchor" href="#_6-红线遵守" aria-label="Permalink to &quot;6. 红线遵守&quot;">​</a></h2><ul><li><strong>禁止 <code>interface</code></strong>：全部使用 <code>type</code> 别名；</li><li><strong>禁止 <code>undefined</code></strong>：空值一律 <code>null</code>，联合类型仅为 <code>T | null</code>；</li><li><strong>禁止任意类型联合</strong>：需要多类型的位置（<code>next</code> 参数、<code>push</code> 的 <code>to</code>）声明为 <code>any</code> 并在此文档写明原因；</li><li><strong>基础类型等值比较</strong>：一律 <code>==</code> / <code>!=</code>；</li><li><strong>数字与数组显式声明类型</strong>；函数参数与返回值显式声明类型，无返回值写 <code>:void</code>；</li><li><strong>类型定义在文件顶层作用域</strong>；</li><li><strong>禁止传递 Class</strong>：用工厂函数 + 类型化对象字面量（箭头函数字段）；</li><li><strong>禁止多层 <code>export *</code></strong>：只有 <code>index.uts</code> 做单层转发；</li><li><strong><code>.uvue</code> 与 <code>&lt;script setup&gt;</code></strong>：本插件是纯逻辑 UTS，不含组件，Vapor / VDOM 差异不适用；</li><li><strong>条件编译</strong>：<code>#ifdef</code> / <code>#ifndef</code> / <code>#endif</code> 不写前缀斜杠；分支内不做自动格式化排序。</li></ul><h2 id="_7-风险与约束" tabindex="-1">7. 风险与约束 <a class="header-anchor" href="#_7-风险与约束" aria-label="Permalink to &quot;7. 风险与约束&quot;">​</a></h2><table tabindex="0"><thead><tr><th>风险</th><th>影响</th><th>处置</th></tr></thead><tbody><tr><td><code>afterEach</code> 触发时机与 vue-router 语义不同</td><td>使用者在「导航失败」时也会收到 afterEach</td><td>已写入 readme 与本文档 5.4；真机验证后可切换</td></tr><tr><td><code>next</code> / <code>to</code> 使用 <code>any</code></td><td>失去该处的静态类型提示</td><td>UTS 联合类型限制所致，无替代方案；类型说明写进 readme</td></tr><tr><td>对象形态<strong>只能直接传字面量</strong>（见 3.4.1）</td><td>使用者若先把 <code>{ path, query }</code> 存进带类型标注的变量再传，App 端会抛 <code>ClassCastException</code>（H5/node 却正常，只在真机暴露）</td><td>不导出对象类型以消除诱导；约束写进 readme；8.3 回归矩阵里加一条「变量承载对象形态」的用例</td></tr><tr><td><code>to.query</code> 是 <code>Map</code> 而非对象（见 3.2）</td><td>与 vue-router 读法不一致</td><td>UTS 无法动态构造 <code>UTSJSONObject</code>，无替代方案；差异写进 readme</td></tr><tr><td>改跳目标是 TabBar 页时必须配 <code>resolveRedirectApi</code></td><td>不配则该次改跳失败（<code>uni.navigateTo</code> 不支持 TabBar 页）</td><td>插件零知识宿主的 TabBar 清单，只能靠可选钩子；readme 给出配置示例</td></tr><tr><td>自定义 API 只能走 <code>UTSJSONObject</code> 分支</td><td>App 端自定义 API 的 options 需自身可被当作 <code>UTSJSONObject</code> 读取</td><td>文档明确；内置 5 个 API 不受影响</td></tr><tr><td>相对路径解析依赖页栈</td><td>页栈为空（如冷启动首个页面）时解析结果可能不符预期</td><td>页栈为空时保持原样不做拼接，并要求使用绝对路径</td></tr><tr><td>插件与 <code>src/router/</code> 同时安装</td><td>两条守卫链同时生效、重复重定向</td><td>readme 明确「二选一」；本期不改造 <code>src/router/</code></td></tr></tbody></table><h2 id="_8-验证计划" tabindex="-1">8. 验证计划 <a class="header-anchor" href="#_8-验证计划" aria-label="Permalink to &quot;8. 验证计划&quot;">​</a></h2><h3 id="_8-1-node-harness-决策矩阵-先写-后实现" tabindex="-1">8.1 node harness 决策矩阵（先写，后实现） <a class="header-anchor" href="#_8-1-node-harness-决策矩阵-先写-后实现" aria-label="Permalink to &quot;8.1 node harness 决策矩阵（先写，后实现）&quot;">​</a></h3><p>项目<strong>当前没有任何测试框架</strong>，按 skill 1.3.13 的做法搭建 node harness，目录 <code>scripts/router-guard-test/</code>（不复用既存的空目录 <code>scripts/guard-test/</code>）：</p><ol><li>把 <code>lib/types.uts</code>、<code>lib/url.uts</code>、<code>lib/guard.uts</code> 按纯文本转换为 <code>.ts</code>（相对导入补 <code>.ts</code> 后缀、UTS 的 <code>a ?: A</code> 可选参数转 TS 的 <code>a?: A</code>、条件编译按目标平台求值）；</li><li><code>stub.ts</code> 补齐运行时全局：<code>uni</code>（<code>addInterceptor</code> / <code>navigateTo</code> 等空实现）、<code>getCurrentPages</code>；</li><li>覆盖：URL 解析与规范化（含相对路径、<code>plugin://</code>、<code>http(s)://</code>、百分号转义）、next 裁决表 6 种形态、守卫链短路顺序、重定向深度保护、放行归零；</li><li><strong>必须验证「把实现改坏时测试会红」</strong> —— 不会红的测试等于没测（skill 红线 28）。</li></ol><p><code>interceptor.uts</code> 因直接调用 <code>uni.addInterceptor</code> 与条件编译强转，不进 harness，改由 8.3 的手工回归覆盖。</p><h3 id="_8-2-真机构建验证" tabindex="-1">8.2 真机构建验证 <a class="header-anchor" href="#_8-2-真机构建验证" aria-label="Permalink to &quot;8.2 真机构建验证&quot;">​</a></h3><p>按 skill 1.3.15，必须使用<strong>不带 <code>--compile</code></strong> 的真机构建：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">/Applications/HBuilderX.app/Contents/MacOS/cli</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> launch</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> app-android</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --project</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /Users/chenqi/Desktop/unibestX</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --deviceId</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">序列</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">号</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span></code></pre></div><p>构建后先确认日志中 <strong><code>编译为android class</code> 出现 ≥ 1 次</strong>，再看 <code>项目 unibestX 编译成功。</code></p><p>（<code>launch app-android --compile true</code> 与 <code>compile app-android --file</code> <strong>不执行</strong> Kotlin 编译阶段，对故意写坏的代码同样报「编译成功」，不可作为验证依据。）</p><h3 id="_8-3-手工回归矩阵" tabindex="-1">8.3 手工回归矩阵 <a class="header-anchor" href="#_8-3-手工回归矩阵" aria-label="Permalink to &quot;8.3 手工回归矩阵&quot;">​</a></h3><p>需要一个临时验证页（不属于交付物，验证后移除），覆盖：</p><ul><li><code>next()</code> 放行 → 导航正常发生，<code>afterEach</code> 触发；</li><li><code>next(&#39;/x&#39;)</code> → 原导航取消、跳到 <code>/x</code>，链条不继续；</li><li><code>next(false)</code> → 无任何跳转；</li><li><code>push({ path: &#39;/xxx&#39;, query: { id: 1 } })</code> 对象形态 → 拼出 <code>/xxx?id=1</code> 并正常跳转；query 值覆盖 <code>string</code> / <code>number</code> / <code>boolean</code> / 数组四种类型（见 3.4.2）；</li><li>「把对象形态存进带类型标注的变量再传」→ 记录真机实际表现，确认与 3.4.1 描述的边界一致；</li><li>未调用 <code>next</code> → 导航取消 + 警告日志；</li><li>5 个 API（<code>navigateTo</code> / <code>redirectTo</code> / <code>reLaunch</code> / <code>switchTab</code> / <code>navigateBack</code>）各自触发拦截；</li><li>相对路径 <code>&#39;subpage?id=1&#39;</code> → 解析为当前页同目录的绝对路径；</li><li>无限重定向（守卫把 A 改跳 B、B 改跳 A）→ 达到 <code>maxRedirectDepth</code> 后停下并打警告。</li></ul><h2 id="_9-交付清单" tabindex="-1">9. 交付清单 <a class="header-anchor" href="#_9-交付清单" aria-label="Permalink to &quot;9. 交付清单&quot;">​</a></h2><table tabindex="0"><thead><tr><th>文件</th><th>动作</th></tr></thead><tbody><tr><td><code>uni_modules/unix-router-guard/package.json</code></td><td>新增（<code>main: &quot;index.uts&quot;</code>，<code>dcloudext.type: &quot;uts&quot;</code>）</td></tr><tr><td><code>uni_modules/unix-router-guard/index.uts</code></td><td>新增（单层门面）</td></tr><tr><td><code>uni_modules/unix-router-guard/lib/types.uts</code></td><td>新增</td></tr><tr><td><code>uni_modules/unix-router-guard/lib/url.uts</code></td><td>新增</td></tr><tr><td><code>uni_modules/unix-router-guard/lib/guard.uts</code></td><td>新增</td></tr><tr><td><code>uni_modules/unix-router-guard/lib/interceptor.uts</code></td><td>新增</td></tr><tr><td><code>uni_modules/unix-router-guard/lib/router.uts</code></td><td>新增</td></tr><tr><td><code>uni_modules/unix-router-guard/readme.md</code></td><td>新增（用法、与 vue-router 的差异、与 <code>src/router</code> 二选一）</td></tr><tr><td><code>uni_modules/unix-router-guard/changelog.md</code></td><td>新增</td></tr><tr><td><code>scripts/router-guard-test/</code></td><td>新增（node harness，不参与主工程编译）</td></tr></tbody></table>`,97)])])}const g=t(o,[["render",d]]);export{h as __pageData,g as default};
